#!/usr/bin/env bash
# Circom / Groth16 end-to-end regression for the integrated Phase-4 circuit.
#
#   compile -> witness (positive vectors) -> public-output check against
#   testdata/kat/canonical_fixture.json -> negative vectors (must be rejected
#   by a circuit assertion) -> Groth16 setup -> prove -> verify (positive
#   vectors) -> tampered public signals must fail verification.
#
# Vectors are generated by circom/scripts/build_canonical_fixture.js.
#
# The Powers-of-Tau file is a LOCAL, single-contributor development ceremony
# with fixed entropy, generated for reproducibility of the test only. It is not
# a production trusted setup.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
REPO="$(cd "$ROOT/.." && pwd)"
TMP="${TMPDIR:-/tmp}/zkep-circom-e2e"
VEC="$ROOT/inputs/eprescription/canonical"
FIXTURE="$REPO/testdata/kat/canonical_fixture.json"
CIRCUIT=08_eprescription_main
PTAU_POWER=15
SNARKJS="${SNARKJS:-snarkjs}"

rm -rf "$TMP"
mkdir -p "$TMP"

echo "== Compile =="
circom "$ROOT/circuits/$CIRCUIT.circom" --r1cs --wasm --sym -o "$TMP"
"$SNARKJS" r1cs info "$TMP/$CIRCUIT.r1cs" | sed -n 's/.*\(# of [A-Za-z ]*:.*\)/\1/p'

WASM="$TMP/${CIRCUIT}_js/$CIRCUIT.wasm"
GEN="$TMP/${CIRCUIT}_js/generate_witness.js"

check_outputs() {
    # $1 = vector id, $2 = witness json
    node -e '
const fx = require(process.argv[1]);
const w = require(process.argv[2]);
const id = process.argv[3];
const e = fx.expected_public_outputs[id];
const hex = (x) => "0x" + BigInt(x).toString(16).padStart(64, "0");
// witness layout: [1, commitment_out, nullifier_out, current_date, root, ...]
const got = { commitment: hex(w[1]), nullifier: hex(w[2]), current_date: BigInt(w[3]).toString(), registry_root: hex(w[4]) };
let ok = true;
for (const k of ["commitment", "nullifier", "current_date", "registry_root"]) {
  if (got[k] !== e[k]) { ok = false; console.log(`  MISMATCH ${k}: got ${got[k]} expected ${e[k]}`); }
}
console.log(`  C=${got.commitment} N=${got.nullifier}`);
process.exit(ok ? 0 : 1);
' "$FIXTURE" "$2" "$1"
}

echo
echo "== Positive witnesses =="
for input in "$VEC"/TV-*.json; do
    id="$(basename "$input" .json)"
    echo "$id"
    node "$GEN" "$WASM" "$input" "$TMP/$id.wtns"
    "$SNARKJS" wtns check "$TMP/$CIRCUIT.r1cs" "$TMP/$id.wtns" >"$TMP/wtns_check.log" 2>&1 \
        || { cat "$TMP/wtns_check.log"; exit 1; }
    grep -q "WITNESS IS CORRECT" "$TMP/wtns_check.log" || { cat "$TMP/wtns_check.log"; exit 1; }
    "$SNARKJS" wtns export json "$TMP/$id.wtns" "$TMP/$id.wtns.json" >/dev/null
    check_outputs "$id" "$TMP/$id.wtns.json"
    echo "  PASS: witness correct, public outputs match fixture"
done

echo
echo "== Negative witnesses =="
for input in "$VEC"/NT-*.json; do
    id="$(basename "$input" .json)"
    if node "$GEN" "$WASM" "$input" "$TMP/negative.wtns" >"$TMP/error.log" 2>&1; then
        echo "FAIL: $id was unexpectedly accepted"
        exit 1
    fi
    if grep -q "Assert Failed" "$TMP/error.log"; then
        where="$(grep -o 'Error in template [A-Za-z0-9_]*' "$TMP/error.log" | head -1)"
        echo "PASS: $id rejected by circuit ($where)"
    else
        echo "FAIL: $id unexpected tool/input error"
        cat "$TMP/error.log"
        exit 1
    fi
done

echo
echo "== Isolated Schnorr verifier vectors =="
circom "$ROOT/circuits/kat/schnorr_unit.circom" --wasm -o "$TMP" >/dev/null
for input in "$ROOT"/inputs/unit/schnorr_canonical/SIG-*.json; do
    id="$(basename "$input" .json)"
    if node "$TMP/schnorr_unit_js/generate_witness.js" "$TMP/schnorr_unit_js/schnorr_unit.wasm" \
        "$input" "$TMP/sig.wtns" >"$TMP/error.log" 2>&1; then
        if [ "$id" = "SIG-OK" ]; then
            echo "PASS: $id accepted"
        else
            echo "FAIL: $id was unexpectedly accepted"; exit 1
        fi
    else
        if [ "$id" = "SIG-OK" ]; then
            echo "FAIL: $id rejected"; cat "$TMP/error.log"; exit 1
        elif grep -q "Assert Failed" "$TMP/error.log"; then
            echo "PASS: $id rejected ($(grep -o 'Error in template [A-Za-z0-9_]*' "$TMP/error.log" | head -1))"
        else
            echo "FAIL: $id unexpected tool/input error"; cat "$TMP/error.log"; exit 1
        fi
    fi
done

echo
echo "== Groth16 setup (local development ceremony) =="
(
    cd "$TMP"
    if [ -n "${ZKEP_PTAU:-}" ]; then
        # Optional reuse of a previously prepared phase-2 ptau (power >= 14).
        echo "Using prepared ptau: $ZKEP_PTAU"
        cp "$ZKEP_PTAU" pot_final.ptau
    else
        "$SNARKJS" powersoftau new bn128 "$PTAU_POWER" pot_0000.ptau >/dev/null
        "$SNARKJS" powersoftau contribute pot_0000.ptau pot_0001.ptau \
            --name="zkep-dev" -e="zkep-dev-entropy" >/dev/null
        "$SNARKJS" powersoftau prepare phase2 pot_0001.ptau pot_final.ptau >/dev/null
    fi
    "$SNARKJS" groth16 setup "$CIRCUIT.r1cs" pot_final.ptau circuit_0000.zkey >/dev/null
    "$SNARKJS" zkey contribute circuit_0000.zkey circuit_final.zkey \
        --name="zkep-dev" -e="zkep-dev-zkey-entropy" >/dev/null
    "$SNARKJS" zkey export verificationkey circuit_final.zkey verification_key.json >/dev/null
)
echo "PASS: setup complete"

echo
echo "== Groth16 prove / verify =="
for input in "$VEC"/TV-*.json; do
    id="$(basename "$input" .json)"
    "$SNARKJS" groth16 prove "$TMP/circuit_final.zkey" "$TMP/$id.wtns" \
        "$TMP/$id.proof.json" "$TMP/$id.public.json" >/dev/null
    "$SNARKJS" groth16 verify "$TMP/verification_key.json" \
        "$TMP/$id.public.json" "$TMP/$id.proof.json" >"$TMP/verify.log" 2>&1 \
        || { cat "$TMP/verify.log"; exit 1; }
    grep -q "OK!" "$TMP/verify.log" || { cat "$TMP/verify.log"; exit 1; }
    echo "PASS: $id proof verified (public: $(tr -d ' \n' < "$TMP/$id.public.json"))"
done

echo
echo "== Tampered public signals must not verify =="
id=TV-001
for idx in 0 1 2 3; do
    node -e '
const fs = require("fs");
const p = JSON.parse(fs.readFileSync(process.argv[1]));
const i = Number(process.argv[2]);
p[i] = (BigInt(p[i]) + 1n).toString();
fs.writeFileSync(process.argv[3], JSON.stringify(p));
' "$TMP/$id.public.json" "$idx" "$TMP/tampered.public.json"
    if "$SNARKJS" groth16 verify "$TMP/verification_key.json" \
        "$TMP/tampered.public.json" "$TMP/$id.proof.json" >"$TMP/verify.log" 2>&1 \
        && grep -q "OK!" "$TMP/verify.log"; then
        echo "FAIL: tampered public signal [$idx] verified"
        exit 1
    fi
    echo "PASS: tampered public signal [$idx] rejected"
done

echo
echo "Circom functional tests passed."
